# http.server + urllib behaviours
import threading, http.server, urllib.request, urllib.error, http.client
class H(http.server.BaseHTTPRequestHandler):
    protocol_version='HTTP/1.1'
    def do_GET(self):
        if self.path=='/r':
            self.send_response(302); self.send_header('Location','http://127.0.0.1:%d/ok'%self.server.server_port); self.send_header('Content-Length','0'); self.end_headers()
        elif self.path=='/e':
            b=b'{"error":1}'; self.send_response(429); self.send_header('Retry-After','50'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
        else:
            b=b'ok'; self.send_response(200); self.send_header('Content-Length','2'); self.end_headers(); self.wfile.write(b)
    def do_DELETE(self):
        self.send_response(204); self.send_header('Content-Length','0'); self.end_headers()
    def log_message(self,*a): pass
s=http.server.ThreadingHTTPServer(('127.0.0.1',0),H); threading.Thread(target=s.serve_forever,daemon=True).start()
p=s.server_port
print('urllib 302 follows ->',urllib.request.urlopen(f'http://127.0.0.1:{p}/r').read())
try: urllib.request.urlopen(f'http://127.0.0.1:{p}/e')
except urllib.error.HTTPError as e: print('HTTPError',e.code,e.headers['Retry-After'],e.read())
r=urllib.request.urlopen(urllib.request.Request(f'http://127.0.0.1:{p}/x',method='DELETE')); print('204 via urllib',r.status,r.read())
c=http.client.HTTPConnection('127.0.0.1',p); c.request('GET','/r'); r=c.getresponse(); print('http.client',r.status,r.getheader('Location'),r.read())
s.shutdown()
try: urllib.request.urlopen(f'http://127.0.0.1:{p}/x',timeout=2)
except Exception as e: print(type(e).__name__, type(e.reason).__name__ if hasattr(e,'reason') else '')
